const runId = Date.now().toString();
const suffix = runId.slice(-8);
pm.collectionVariables.set('testRunId', runId);
pm.collectionVariables.set('testEmail', `newman_${runId}@edulearn.test`);
pm.collectionVariables.set('testPhone', `09${suffix}`);
pm.collectionVariables.set('testPassword', 'Pass123!@#');
pm.collectionVariables.set('couponPercentCode', `PCT${suffix}`);
pm.collectionVariables.set('couponFixedCode', `FIX${suffix}`);
pm.collectionVariables.set('couponExpiredCode', `EXP${suffix}`);
pm.collectionVariables.set('couponMinCode', `MIN${suffix}`);
pm.collectionVariables.unset('authToken');
pm.collectionVariables.unset('adminToken');
pm.collectionVariables.unset('orderId');
pm.collectionVariables.unset('affiliateId');
pm.collectionVariables.unset('affiliateCode');

pm.test('TC-01 - Status 201 Created', () => {
    pm.response.to.have.status(201);
});

pm.test('TC-01 - Response time dưới 2000ms', () => {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test('TC-01 - Có thông báo tạo tài khoản thành công', () => {
    const json = pm.response.json();

    pm.expect(json).to.have.property('message');
    pm.expect(json.message).to.be.a('string').and.not.empty;
});

pm.test('TC-01 - Không làm lộ password', () => {
    const json = pm.response.json();
    pm.expect(json).to.not.have.property('password');
});

pm.test('TC-01 - Register không trả JWT token', () => {
    const json = pm.response.json();
    pm.expect(json).to.not.have.property('token');
});

pm.test('TC-01 - Register không trả user object', () => {
    const json = pm.response.json();
    pm.expect(json).to.not.have.property('user');
});
